const $=id=>document.getElementById(id);let state=null,nightOnly=false,selected=0,request=0;const rad=180/Math.PI;const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Forecast service returned '+r.status);return r.json()}
function fmt(d,opts={hour:'numeric',minute:'2-digit'}){if(!d||!Number.isFinite(+d))return 'Not in this period';return new Intl.DateTimeFormat('en-US',{timeZone:state.zone,...opts}).format(d)}
function quality(n){return n>=70?'Good':n>=40?'Fair':'Poor'}function scoreFor(cloud,humidity,wind,sun,moon,illum){if(sun>=0)return 0;const raw=(100-cloud)*.6+(100-Math.max(0,humidity-40)*1.4)*.15+Math.max(0,100-wind*3)*.1+(100-(moon>0?illum*100:0))*.15;return Math.round(Math.max(0,Math.min(100,raw))*(sun<-18?1:sun<-12?.65:.25))}
async function load(lat,lon,name){const token=++request;$('status').textContent='Updating local forecast…';try{const data=await json('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&hourly=temperature_2m,relative_humidity_2m,cloud_cover,wind_speed_10m,precipitation_probability&forecast_days=3&timezone=auto&timeformat=unixtime');if(token!==request)return;const now=new Date(),end=new Date(+now+86400000),moon=SunCalc.getMoonIllumination(now);let hours=data.hourly.time.map((t,i)=>{const date=new Date(t*1000),sun=SunCalc.getPosition(date,lat,lon).altitude*rad,mp=SunCalc.getMoonPosition(date,lat,lon);return{date,sun,moonAlt:mp.altitude*rad,cloud:data.hourly.cloud_cover[i],humidity:data.hourly.relative_humidity_2m[i],wind:data.hourly.wind_speed_10m[i],temp:data.hourly.temperature_2m[i],rain:data.hourly.precipitation_probability[i],score:scoreFor(data.hourly.cloud_cover[i],data.hourly.relative_humidity_2m[i],data.hourly.wind_speed_10m[i],sun,mp.altitude,SunCalc.getMoonIllumination(date).fraction)}}).filter(h=>+h.date>=+now&&+h.date<+end);if(hours.length!==24)throw Error('Incomplete 24-hour forecast');const samples=[];for(let t=+now;t<=+end;t+=300000)samples.push({date:new Date(t),alt:SunCalc.getPosition(new Date(t),lat,lon).altitude*rad});const darkMinutes=samples.slice(0,-1).filter(s=>s.alt<-18).length*5;const events=[];for(let i=1;i<samples.length;i++){for(const [alt,label,icon,sub] of [[-.833,'Sunset','☀','The Sun dips below the horizon'],[-18,'Astronomical dusk','✦','True darkness begins']]){if(samples[i-1].alt>=alt&&samples[i].alt<alt)events.push({date:samples[i].date,label,icon,sub});if(samples[i-1].alt<alt&&samples[i].alt>=alt)events.push({date:samples[i].date,label:alt===-18?'Astronomical dawn':'Sunrise',icon:alt===-18?'✧':'☀',sub:alt===-18?'True darkness ends':'The Sun returns above the horizon'});}}let best=hours.reduce((a,b)=>b.score>a.score?b:a);state={lat,lon,name,zone:data.timezone,hours,moon,darkMinutes,events,best,now};selected=hours.indexOf(best);render();$('status').textContent='';try{localStorage.setItem('nightwatch-location',JSON.stringify({lat,lon,name}))}catch{}}catch(e){if(token===request){$('status').textContent='Couldn’t update the forecast. Check your connection and try another search or refresh. '+(state?'The previous location remains displayed.':'');$('updated').textContent='Live forecast unavailable';$('headline').textContent=state?$('headline').textContent:'The sky will be here.';$('summary').textContent=state?$('summary').textContent:'Search for a city or use your location to try again.';}}}
function render(){const s=state,b=s.best,illum=Math.round(s.moon.fraction*100);$('place').textContent=s.name;$('updated').textContent='Updated '+fmt(s.now)+' · live forecast';$('zone').textContent=s.zone.replaceAll('_',' ')+' · local time';$('score').textContent=b.score;$('rating').textContent=quality(b.score)+' observing conditions';$('headline').innerHTML=b.score>=70?'A night worth<br>looking up for.':b.score>=40?'A few stars.<br>A little patience.':s.darkMinutes?'A quieter night<br>for the stars.':'A sky without<br>true darkness.';$('summary').textContent=b.score>=70?'Clearer skies and darkness align. Find a quiet spot, let your eyes adjust, and take it all in.':b.score>=40?'There may be a chance to catch the stars. Watch the hourly conditions for a clearer opening.':s.darkMinutes?'Clouds or moonlight may limit the view. Check the hourly forecast before heading out.':'The Sun stays above −18° during this forecast. Deep-sky observing will be limited.';let candidates=[];for(let i=0;i<s.hours.length;i++){const block=s.hours.slice(i,i+3);if(block.every(h=>h.sun<-18))candidates.push({block,avg:block.reduce((a,h)=>a+h.score,0)/block.length});}const window=candidates.sort((a,b)=>b.avg-a.avg)[0];$('best').textContent=window?'✧ Best window '+fmt(window.block[0].date)+'–'+fmt(new Date(+window.block.at(-1).date+3600000)):'✧ No fully dark viewing window';$('dark').textContent='☾ '+(s.darkMinutes/60).toFixed(1)+' hours of true darkness';$('cloud').textContent=b.cloud+'%';$('moon').textContent=illum+'%';const p=s.moon.phase;$('phase').textContent=p<.03||p>.97?'New moon':p<.25?'Waxing crescent':p<.28?'First quarter':p<.48?'Waxing gibbous':p<.53?'Full moon':p<.75?'Waning gibbous':p<.78?'Last quarter':'Waning crescent';$('darkhours').textContent=(s.darkMinutes/60).toFixed(1)+' hrs';$('wind').textContent=Math.round(b.wind)+' km/h';$('events').innerHTML=s.events.length?s.events.sort((a,b)=>a.date-b.date).map(e=>'<div class="event"><span>'+e.icon+'</span><div><b>'+e.label+'</b><small>'+e.sub+'</small></div><time>'+fmt(e.date)+'</time></div>').join(''):'<p>No sunrise, sunset, or astronomical twilight crossings in the next 24 hours at this latitude.</p>';renderHours()}
function renderHours(){if(!state)return;const hours=state.hours.map((h,i)=>({...h,i})).filter(h=>!nightOnly||h.sun<-18);$('hours').innerHTML=hours.length?hours.map(h=>'<button class="hour '+(selected===h.i?'selected':'')+'" data-hour="'+h.i+'" aria-label="'+escapeText(fmt(h.date)+', score '+h.score+', cloud '+h.cloud+' percent')+'"><span>'+fmt(h.date,{hour:'numeric'})+'</span><b>'+(h.sun>=0?'☀':h.cloud>65?'☁':h.cloud>25?'☾':'✧')+'</b><span class="bar"><i style="height:'+Math.max(5,h.score)+'%;background:'+(h.score>=70?'#c2e8aa':h.score>=40?'#bdac73':'#5d7074')+'"></i></span><strong>'+h.score+'</strong><span>'+h.cloud+'% ☁</span></button>').join(''):'<p>No astronomical dark hours in the next 24 hours.</p>';const h=state.hours[selected];$('detail').textContent=fmt(h.date,{weekday:'short',hour:'numeric',minute:'2-digit'})+' · '+(h.sun>=0?'Daylight':h.sun<-18?'Astronomical darkness':'Twilight')+' · '+h.cloud+'% cloud · '+h.temp+'°C · '+h.humidity+'% humidity · '+Math.round(h.wind)+' km/h wind · '+h.rain+'% rain chance · Moon '+(h.moonAlt>0?'above':'below')+' horizon';document.querySelectorAll('[data-hour]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.hour);renderHours()})}
$('search').onsubmit=async e=>{e.preventDefault();const term=$('city').value.trim();if(term.length<2){$('status').textContent='Enter at least two letters of a city name.';return;}$('status').textContent='Searching locations…';try{const d=await json('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(term)+'&count=6&language=en&format=json');$('results').replaceChildren();if(!d.results?.length){$('status').textContent='No matching cities. Try a nearby town or another spelling.';return;}d.results.forEach(r=>{const name=[r.name,r.admin1,r.country].filter(Boolean).join(', ');const button=document.createElement('button');button.textContent=name;button.onclick=()=>{$('results').replaceChildren();$('city').value='';load(r.latitude,r.longitude,name)};$('results').append(button)});$('status').textContent='Choose a location above.'}catch{$('status').textContent='Location search is unavailable. Please try again.'}};
$('locate').onclick=()=>{if(!navigator.geolocation){$('status').textContent='Device location is unavailable. Search for a city instead.';return;}$('status').textContent='Waiting for your location…';navigator.geolocation.getCurrentPosition(p=>load(p.coords.latitude,p.coords.longitude,'Your location · '+p.coords.latitude.toFixed(2)+'°, '+p.coords.longitude.toFixed(2)+'°'),()=>{$('status').textContent='Location access was unavailable. Search for a city to see your forecast.'},{timeout:12000,maximumAge:300000})};$('all').onclick=()=>{nightOnly=false;$('all').classList.add('active');$('night').classList.remove('active');renderHours()};$('night').onclick=()=>{nightOnly=true;$('night').classList.add('active');$('all').classList.remove('active');renderHours()};$('red').onclick=()=>{$('red').setAttribute('aria-pressed',document.body.classList.toggle('red'))};$('method').onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();document.addEventListener('keydown',e=>{if(e.key==='Escape')$('results').replaceChildren()});let saved;try{saved=JSON.parse(localStorage.getItem('nightwatch-location'))}catch{}if(saved&&Number.isFinite(saved.lat)&&Number.isFinite(saved.lon))load(saved.lat,saved.lon,saved.name);else load(35.1983,-111.6513,'Flagstaff, Arizona · Example location');
